import {topics,photoNotes,photoTask,viewPoint,cropFor,distance,iou} from './photo-data.js';
const $=id=>document.getElementById(id),canvas=$('photoCanvas'),ctx=canvas.getContext('2d');
const sources=await (await fetch('./photos/attribution.json')).json();
let serial=1,task=photoTask(1,'thirds'),image=new Image(),own=null,crop={x:0,y:0,w:1,h:1},marks=[],draft=null,example=false,guide='thirds',spiralTurn=0,history=[];
try{history=JSON.parse(localStorage.getItem('cct-photo-history-v1')||'[]').slice(-100);}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
for(const topic of topics){const o=document.createElement('option');o.value=topic.id;o.textContent=topic.name;$('photoTopic').append(o);}
const full=()=>({x:0,y:0,w:1,h:1});const pt=p=>task.mirror?[1-p[0],p[1]]:p;
function note(){const n=structuredClone(photoNotes[task.id]);for(const key of ['anchor','vp'])if(n[key])n[key]=pt(n[key]);if(n.axis!==undefined&&task.mirror)n.axis=1-n.axis;if(n.frame&&task.mirror)n.frame[0]=1-n.frame[0]-n.frame[2];for(const key of ['lines','layers','balance'])if(n[key])n[key]=n[key].map(p=>p.length===4?[...pt(p.slice(0,2)),...pt(p.slice(2))]:pt(p));return n;}
function reference(){const n=note(),id=task.topic.id;let c=full(),m=[];
 if(['thirds','golden','center','negative'].includes(id)){const target=id==='center'?[.5,.5]:id==='negative'?[task.mirror?.2:.8,.5]:id==='golden'?[task.mirror?.382:.618,.618]:[task.mirror?1/3:2/3,2/3];c=cropFor(n.anchor,target,id==='negative'?.65:.5);}
 if(['vanishing','spiral'].includes(id))m=[{type:'point',p:n.vp||n.anchor}];
 if(id==='symmetry')m=[{type:'line',a:[n.axis,.1],b:[n.axis,.9]}];
 if(id==='leading')m=n.lines.slice(0,2).map(p=>({type:'line',a:p.slice(0,2),b:p.slice(2)}));
 if(id==='frame')m=[{type:'box',a:n.frame.slice(0,2),b:[n.frame[0]+n.frame[2],n.frame[1]+n.frame[3]]}];
 if(id==='balance')m=n.balance.map(p=>({type:'point',p}));if(id==='depth')m=n.layers.map(p=>({type:'point',p}));return{crop:c,marks:m};}
function segment(m,c){const a=viewPoint(m.a,c),b=viewPoint(m.b,c);ctx.beginPath();ctx.moveTo(a[0]*canvas.width,a[1]*canvas.height);ctx.lineTo(b[0]*canvas.width,b[1]*canvas.height);ctx.stroke();}
function drawGuides(c,m){ctx.strokeStyle='#ffffffaa';ctx.lineWidth=2;const w=canvas.width,h=canvas.height;
 if(['thirds','golden','center'].includes(guide)){const values=guide==='thirds'?[1/3,2/3]:guide==='golden'?[.382,.618]:[.5];for(const v of values){ctx.beginPath();ctx.moveTo(v*w,0);ctx.lineTo(v*w,h);ctx.moveTo(0,v*h);ctx.lineTo(w,v*h);ctx.stroke();}}
 if(guide==='diagonal'){ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(w,h);ctx.moveTo(w,0);ctx.lineTo(0,h);ctx.stroke();}
 if(guide==='spiral'){const focus=m.find(x=>x.type==='point')?.p||(own?[.5,.5]:note().anchor),f=viewPoint(focus,c);ctx.beginPath();for(let i=0;i<=240;i++){const theta=i/240*Math.PI*4,r=.006*Math.pow(1.618,theta/(Math.PI/2)),x=f[0]*w+Math.cos(theta+spiralTurn)*r*Math.min(w,h),y=f[1]*h+Math.sin(theta+spiralTurn)*r*Math.min(w,h);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}
}
function draw(c=example?reference().crop:crop,m=example?reference().marks:marks,showGuide=true){if(!image.complete||!image.naturalWidth)return;canvas.width=Math.round(Math.min(1280,image.naturalWidth)*c.w);canvas.height=Math.round(canvas.width*image.naturalHeight/image.naturalWidth*c.h/c.w);ctx.save();ctx.clearRect(0,0,canvas.width,canvas.height);if(task.mirror){ctx.translate(canvas.width,0);ctx.scale(-1,1);}const sourceX=(task.mirror?1-c.x-c.w:c.x)*image.naturalWidth;ctx.drawImage(image,sourceX,c.y*image.naturalHeight,c.w*image.naturalWidth,c.h*image.naturalHeight,0,0,canvas.width,canvas.height);ctx.restore();if(showGuide)drawGuides(c,m);ctx.strokeStyle=example?'#ffbf68':'#8ff6d2';ctx.fillStyle=ctx.strokeStyle;ctx.lineWidth=3;
 m.forEach((mark,i)=>{if(mark.type==='point'){const p=viewPoint(mark.p,c);ctx.beginPath();ctx.arc(p[0]*canvas.width,p[1]*canvas.height,8,0,Math.PI*2);ctx.stroke();ctx.font='bold 18px sans-serif';ctx.fillText(i+1,p[0]*canvas.width+12,p[1]*canvas.height-10);}else if(mark.type==='line')segment(mark,c);else{const a=viewPoint(mark.a,c),b=viewPoint(mark.b,c);ctx.strokeRect(a[0]*canvas.width,a[1]*canvas.height,(b[0]-a[0])*canvas.width,(b[1]-a[1])*canvas.height);}});
 if(draft){ctx.setLineDash([8,5]);if(draft.type==='line')segment(draft,c);else{const a=viewPoint(draft.a,c),b=viewPoint(draft.b,c);ctx.strokeRect(a[0]*canvas.width,a[1]*canvas.height,(b[0]-a[0])*canvas.width,(b[1]-a[1])*canvas.height);}ctx.setLineDash([]);}}
function syncCrop(){$('cropScale').value=Math.min(crop.w,crop.h);$('cropScaleValue').textContent=Math.round(crop.w*100)+'% × '+Math.round(crop.h*100)+'%';$('cropX').value=crop.x/Math.max(.001,1-crop.w);$('cropY').value=crop.y/Math.max(.001,1-crop.h);}
async function load(taskNew=task){task=taskNew;own=null;crop=full();marks=[];draft=null;example=false;guide=task.topic.guide;$('photoTopic').value=task.topic.id;$('photoTool').value=task.topic.tool;$('photoGuide').value=guide;$('photoGoal').textContent=task.mirror&&task.topic.id==='negative'?task.topic.goal.replace('인물 왼쪽','인물 오른쪽'):task.topic.goal;$('photoTheory').textContent=task.topic.theory;$('photoTitle').textContent=`문제 ${task.serial} · ${photoNotes[task.id].name}${task.mirror?' · 좌우 반전':''}`;const source=sources.find(s=>s.id===task.id);$('photoSource').innerHTML=`사진: ${esc(source.author)} · <a href="${esc(source.url)}" target="_blank" rel="noopener">원본 출처</a> · <a href="${esc(source.licenseUrl)}" target="_blank" rel="noopener">${esc(source.license)}</a>${task.mirror?' · 학습용 좌우 반전 표시':''}`;image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('사진을 불러오지 못했습니다.'));image.src=source.file;});$('photoFeedback').replaceChildren();$('photoComparison').hidden=true;view(false);syncCrop();draw();}
function view(v){example=v;$('photoExample').classList.toggle('active',v);$('photoMine').classList.toggle('active',!v);$('photoStatus').textContent=v?'예시 표시 중 · 내 표시와 크롭은 보존됩니다.':'내 표시 편집 중';draw();}
function pointer(e){const r=canvas.getBoundingClientRect();return[crop.x+(e.clientX-r.left)/r.width*crop.w,crop.y+(e.clientY-r.top)/r.height*crop.h].map(v=>Math.min(1,Math.max(0,v)));}
canvas.onpointerdown=e=>{if(example)view(false);canvas.setPointerCapture(e.pointerId);const p=pointer(e),tool=$('photoTool').value;if(tool==='point'){marks.push({type:'point',p});draw();}else{draft={type:tool,a:p,b:p};draw();}};
canvas.onpointermove=e=>{if(draft){draft.b=pointer(e);draw();}};canvas.onpointerup=e=>{if(!draft)return;draft.b=pointer(e);if(distance(draft.a,draft.b)>.01){if(draft.type==='crop'){const x=Math.min(draft.a[0],draft.b[0]),y=Math.min(draft.a[1],draft.b[1]),w=Math.abs(draft.a[0]-draft.b[0]),h=Math.abs(draft.a[1]-draft.b[1]);if(w>=.08&&h>=.08)marks.push({type:'crop',a:[x,y],b:[x+w,y+h]});}else marks.push(draft);}draft=null;draw();};canvas.onpointercancel=()=>{draft=null;draw();};
$('cropApply').onclick=()=>{const box=[...marks].reverse().find(m=>m.type==='crop');if(!box){$('photoStatus').textContent='크롭 도구로 사각형을 먼저 그리세요.';return;}crop={x:box.a[0],y:box.a[1],w:box.b[0]-box.a[0],h:box.b[1]-box.a[1]};marks=marks.filter(m=>m.type!=='crop');view(false);syncCrop();};$('cropReset').onclick=()=>{crop=full();view(false);syncCrop();};
$('cropScale').oninput=()=>{const scale=Number($('cropScale').value);crop={x:Math.min(crop.x,1-scale),y:Math.min(crop.y,1-scale),w:scale,h:scale};view(false);syncCrop();};for(const id of ['cropX','cropY'])$(id).oninput=()=>{crop[id==='cropX'?'x':'y']=Number($(id).value)*(1-(id==='cropX'?crop.w:crop.h));view(false);syncCrop();};
$('photoGuide').onchange=()=>{guide=$('photoGuide').value;draw();};$('spiralFlip').onclick=()=>{spiralTurn+=Math.PI/2;draw();};$('photoUndo').onclick=()=>{marks.pop();view(false);};$('photoClear').onclick=()=>{marks=[];view(false);};$('photoMine').onclick=()=>view(false);$('photoExample').onclick=()=>{if(own){$('photoStatus').textContent='내 사진에는 지정된 정답 예시가 없습니다. 가이드로 자유롭게 비교하세요.';return;}view(true);};
$('photoTopic').onchange=()=>{serial++;load(photoTask(serial,$('photoTopic').value)).catch(e=>$('photoStatus').textContent=e.message);};$('photoNext').onclick=()=>{serial++;load(photoTask(serial)).catch(e=>$('photoStatus').textContent=e.message);};$('photoReset').onclick=()=>own?(marks=[],crop=full(),view(false),syncCrop()):load(task);$('builtinPhoto').onclick=()=>load(photoTask(task.serial,task.topic.id));
function evaluate(){if(own)return{passed:null,text:'내 사진 자유 연습: 피사체·선·공간의 의미는 자동 인식하지 않습니다. 가이드를 바꾸고 원본과 크롭을 비교하며 무엇을 강조했는지 직접 확인하세요.'};const n=note(),id=task.topic.id,points=marks.filter(m=>m.type==='point').map(m=>m.p),lines=marks.filter(m=>m.type==='line');let passed=false,text='';
 if(['thirds','golden','center','negative'].includes(id)){const p=viewPoint(n.anchor,crop);if(id==='center'){passed=distance(p,[.5,.5])<.1;text=`강조점의 화면 위치: 가로 ${Math.round(p[0]*100)}%, 세로 ${Math.round(p[1]*100)}%. 중앙에서의 거리 ${(distance(p,[.5,.5])*100).toFixed(1)}%p.`;}else if(id==='negative'){passed=(task.mirror?p[0]>=.1&&p[0]<=.35:p[0]>=.65&&p[0]<=.9)&&p[1]>0&&p[1]<1;text=`인물 위치: 가로 ${Math.round(p[0]*100)}%. 진행 과제에서 지정한 쪽의 공간을 확보했는지 확인합니다.`;}else{const v=id==='golden'?[.382,.618]:[1/3,2/3],d=Math.min(...v.flatMap(x=>v.map(y=>distance(p,[x,y]))));passed=d<.1;text=`가장 가까운 ${id==='golden'?'황금분할':'삼분할'} 교차점과의 거리 ${(d*100).toFixed(1)}%p. 공식 일치와 미적 완성도는 별개입니다.`;}}
 if(['vanishing','spiral'].includes(id)){const d=points.length?Math.min(...points.map(p=>distance(p,n.vp||n.anchor))):Infinity;passed=d<.09;text=id==='vanishing'?`복도 경계가 모이는 참고 소실점 부근을 ${passed?'찾았습니다.':'다시 살펴보세요.'}`:'찍은 강조점이 주요 피사체 부근인지 확인합니다. 나선은 배치 실험용이며 사진이 원래 황금나선이라고 판정하지 않습니다.';}
 if(id==='symmetry'){passed=lines.some(l=>Math.abs(l.a[0]-n.axis)<.08&&Math.abs(l.b[0]-n.axis)<.08&&Math.abs(l.a[1]-l.b[1])>.35);text='아치 또는 복도의 구조적 중심축을 확인합니다. 주변 나무·건물·빛 때문에 완벽한 좌우 대칭은 아닙니다.';}
 if(id==='leading'){const matched=new Set();for(const l of lines)for(let i=0;i<n.lines.length;i++){const r=n.lines[i],d=Math.min(distance(l.a,r.slice(0,2))+distance(l.b,r.slice(2)),distance(l.b,r.slice(0,2))+distance(l.a,r.slice(2)));if(d<.28)matched.add(i);}passed=matched.size>=2;text=`대표 경계 ${matched.size}개와 표시가 가깝습니다. 곡선·다른 선의 해석은 이 간단한 검사에 포함되지 않습니다.`;}
 if(id==='frame'){passed=marks.filter(m=>m.type==='box').some(m=>iou([Math.min(m.a[0],m.b[0]),Math.min(m.a[1],m.b[1]),Math.abs(m.a[0]-m.b[0]),Math.abs(m.a[1]-m.b[1])],n.frame)>.45);text='아치가 뒤쪽 공간을 둘러싸는 영역과 사각형 표시의 겹침을 확인합니다.';}
 if(id==='balance'){passed=n.balance.every(p=>points.some(q=>distance(p,q)<.12));text='밝은 노을과 어두운 인물을 두 관심 영역으로 확인합니다. 시각적 균형의 미적 좋고 나쁨은 점수화하지 않습니다.';}
 if(id==='depth'){passed=points.length>=3&&n.layers.every((p,i)=>distance(p,points[i])<.22);text='처음 3개 표시를 전경 → 중경 → 배경 예시와 비교합니다. 넓은 공간의 층에는 다른 대표점도 가능합니다.';}
 return{passed,text};}
function imageOf(c,m,withGuide){const prev=draft;draft=null;draw(c,m,withGuide);const data=canvas.toDataURL('image/jpeg',.86);draft=prev;draw();return data;}
function compare(){const ref=own?{crop:full(),marks:[]}:reference();$('photoComparison').innerHTML=`<div class="photo-comparisons">${[[full(),[],'원본',false],[crop,marks,'내 표시·크롭',true],[ref.crop,ref.marks,own?'원본 + 가이드':'예시 · 가능한 선택 하나',true]].map(([c,m,label,g])=>`<figure><img alt="${label}" src="${imageOf(c,m,g)}"><figcaption>${label}</figcaption></figure>`).join('')}</div><p>크롭으로 주변 정보가 얼마나 사라졌는지 확인하세요. 피사체를 공식에 맞추려고 가지·발·전경을 불필요하게 잘랐다면 다른 배치도 시도해 보세요.</p>`;$('photoComparison').hidden=false;}
$('photoCompare').onclick=compare;$('photoEvaluate').onclick=()=>{view(false);const r=evaluate();$('photoFeedback').innerHTML=`<div class="check-card ${r.passed?'good':'improve'}"><strong>${r.passed===null?'자유 비교':r.passed?'✓ 이번 표시·배치 조건 충족':'△ 다른 표시·배치도 확인하기'}</strong><p>${esc(r.text)}</p><p>${esc(task.topic.theory)}</p></div>`;compare();if(!own){history.push({at:new Date().toISOString(),task:{serial:task.serial,topic:task.topic.id},crop:structuredClone(crop),marks:structuredClone(marks),passed:r.passed});history=history.slice(-100);try{localStorage.setItem('cct-photo-history-v1',JSON.stringify(history));}catch{$('photoStatus').textContent='학습 기록 저장 공간이 부족합니다.';}historyUI();}};
function session(){return{version:1,serial:task.serial,topic:task.topic.id,crop,marks,guide,own,history};}
function valid(s){if(s?.version!==1||!topics.some(t=>t.id===s.topic)||!Number.isInteger(s.serial)||s.serial<1)throw Error('지원하지 않는 사진 학습 백업입니다.');const c=s.crop;if(!c||![c.x,c.y,c.w,c.h].every(Number.isFinite)||c.x<0||c.y<0||c.w<.08||c.h<.08||c.x+c.w>1.001||c.y+c.h>1.001)throw Error('크롭 범위를 확인하세요.');if(!Array.isArray(s.marks)||s.marks.length>500)throw Error('표시 정보가 잘못되었습니다.');for(const m of s.marks){if(!['point','line','box','crop'].includes(m.type))throw Error('표시 형식이 잘못되었습니다.');for(const p of m.type==='point'?[m.p]:[m.a,m.b])if(!Array.isArray(p)||p.length!==2||!p.every(v=>Number.isFinite(v)&&v>=0&&v<=1))throw Error('표시 좌표가 잘못되었습니다.');}if(s.own&&!/^data:image\/(png|jpeg|webp);base64,/.test(s.own))throw Error('내 사진 형식이 잘못되었습니다.');return s;}
async function restore(raw){const s=valid(raw);serial=s.serial;await load(photoTask(s.serial,s.topic));if(s.own){own=s.own;await setOwnImage(own);}crop=s.crop;marks=s.marks;guide=['none','thirds','golden','center','spiral','diagonal'].includes(s.guide)?s.guide:'none';$('photoGuide').value=guide;history=Array.isArray(s.history)?s.history.slice(-100):history;try{localStorage.setItem('cct-photo-history-v1',JSON.stringify(history));}catch{}syncCrop();view(false);historyUI();}
$('photoSave').onclick=()=>{try{localStorage.setItem('cct-photo-session-v1',JSON.stringify(session()));$('photoStatus').textContent='사진 연습을 저장했습니다.';}catch{$('photoStatus').textContent='저장 공간이 부족합니다. JSON 백업을 사용하세요.';}};$('photoLoad').onclick=async()=>{try{const raw=localStorage.getItem('cct-photo-session-v1');if(!raw)throw Error('저장된 사진 연습이 없습니다.');await restore(JSON.parse(raw));$('photoStatus').textContent='사진 연습을 불러왔습니다.';}catch(e){$('photoStatus').textContent=e.message;}};
$('photoExport').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(session())],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='photo-composition-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};$('photoImport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>8000000)throw Error('백업 파일이 너무 큽니다.');await restore(JSON.parse(await f.text()));$('photoStatus').textContent='백업을 복원했습니다.';}catch(e){$('photoStatus').textContent=e.message;}e.target.value='';};
async function setOwnImage(data){task.mirror=false;image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('사진을 열 수 없습니다.'));image.src=data;});$('photoTitle').textContent='내 사진 · 자유 구도 연습';$('photoSource').textContent='내 기기의 사진 · 외부 업로드 없음';$('photoGoal').textContent='점·선·영역을 표시하고 구도 가이드와 크롭을 바꿔 비교하세요. 이 사진의 피사체나 소실점을 자동으로 판정하지 않습니다.';}
$('ownPhoto').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>25000000)throw Error('25MB 이하의 사진을 사용하세요.');const url=URL.createObjectURL(f),temp=new Image();try{await new Promise((resolve,reject)=>{temp.onload=resolve;temp.onerror=()=>reject(Error('이 사진 형식을 열 수 없습니다. JPEG 또는 PNG를 사용하세요.'));temp.src=url;});const buffer=document.createElement('canvas');buffer.width=Math.min(1600,temp.naturalWidth);buffer.height=buffer.width*temp.naturalHeight/temp.naturalWidth;buffer.getContext('2d').drawImage(temp,0,0,buffer.width,buffer.height);own=buffer.toDataURL('image/jpeg',.88);}finally{URL.revokeObjectURL(url);}task.mirror=false;await setOwnImage(own);crop=full();marks=[];view(false);syncCrop();}catch(e){$('photoStatus').textContent=e.message;}e.target.value='';};
function historyUI(){$('photoProgress').textContent=`사진 학습 기록 · 최근 ${history.length}회`;$('photoHistory').replaceChildren();for(const h of [...history].reverse().slice(0,20)){if(!h?.task)continue;const t=topics.find(t=>t.id===h.task.topic);if(!t)continue;const b=document.createElement('button');b.textContent=`${t.name} · ${h.passed?'조건 충족':'재검토'} · ${new Date(h.at).toLocaleDateString('ko-KR')}`;b.onclick=()=>restore({version:1,serial:h.task.serial,topic:h.task.topic,crop:h.crop,marks:h.marks,guide:t.guide,history});$('photoHistory').append(b);}}
window.__photo={snapshot:()=>structuredClone(session()),reference:()=>reference(),evaluate,restore,ready:()=>image.complete&&image.naturalWidth>0};
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});await load();historyUI();
